#!/usr/bin/env node
// Scratch probe: measure the phone shell (hero clamp, map top) over CDP.
import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const BASE = process.argv[2] || 'http://127.0.0.1:8787';
const PORT = 9333;
const CHROME = ['chromium', 'chromium-browser', 'google-chrome', 'google-chrome-stable'].find((bin) => {
  for (const dir of (process.env.PATH || '').split(':')) if (dir && existsSync(path.join(dir, bin))) return true;
  return false;
});
if (!CHROME) throw new Error('no chromium');
const profile = path.join(os.tmpdir(), `cdp-probe-${process.pid}`);
const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-sandbox', '--no-first-run', '--disable-dev-shm-usage',
  `--remote-debugging-port=${PORT}`, `--user-data-dir=${profile}`, 'about:blank',
], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let ws;
for (let i = 0; i < 50; i += 1) {
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
    const list = await res.json();
    const page = list.find((t) => t.type === 'page');
    if (page) { ws = new WebSocket(page.webSocketDebuggerUrl); break; }
  } catch { /* not up yet */ }
  await sleep(200);
}
if (!ws) throw new Error('no devtools target');
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve); ws.addEventListener('error', reject); });
let id = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error))); else resolve(msg.result);
  }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  id += 1;
  pending.set(id, { resolve, reject });
  ws.send(JSON.stringify({ id, method, params }));
});
const evaluate = async (expression) => {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (res.exceptionDetails) throw new Error(res.exceptionDetails.text);
  return res.result.value;
};

await send('Page.enable');
for (const width of [320, 360, 390, 430, 600]) {
  await send('Emulation.setDeviceMetricsOverride', { width, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: `${BASE}/` });
  await sleep(2500);
  const m = await evaluate(`(() => {
    const map = document.querySelector('#map, .app-map, [data-map]');
    const hero = document.querySelector('.app-intro');
    const lead = document.querySelector('.app-intro .zh-lead');
    const facts = document.querySelector('#intro-facts');
    const r = (n) => n ? n.getBoundingClientRect() : null;
    const lines = (n) => n ? Math.round(n.getBoundingClientRect().height / parseFloat(getComputedStyle(n).lineHeight)) : null;
    const mapRect = r(map);
    return {
      width: window.innerWidth,
      mapTop: mapRect ? Math.round(mapRect.top) : null,
      mapVisible: mapRect ? Math.round(Math.max(0, Math.min(window.innerHeight, mapRect.bottom) - Math.max(0, mapRect.top))) : null,
      heroH: hero ? Math.round(hero.getBoundingClientRect().height) : null,
      leadH: lead ? Math.round(lead.getBoundingClientRect().height) : null,
      leadScrollH: lead ? Math.round(lead.scrollHeight) : null,
      leadClamped: lead ? lead.scrollHeight > lead.clientHeight + 1 : null,
      leadLines: lines(lead),
      leadText: lead ? lead.textContent.replace(/\\s+/g, ' ').trim() : null,
      factsVisible: facts ? getComputedStyle(facts).display !== 'none' : null,
      factsH: facts ? Math.round(facts.getBoundingClientRect().height) : null,
      headerH: Math.round(document.querySelector('header').getBoundingClientRect().height),
      overflow: document.documentElement.scrollWidth - window.innerWidth,
    };
  })()`);
  console.log(JSON.stringify(m));
}
chrome.kill('SIGTERM');

